insert into public.team_members (name, role_title, bio, qualifications, focus_areas, is_owner, visible, sort_order) values ($str$Jürgen Pollack$str$, $str$Inhaber und Geschäftsführer$str$, $str$Seit 1987 auf der Matte und im Kraftraum zuhause: Jürgen Pollack hat den Sportpark Pollack aus Überzeugung aufgebaut – dass Training mehr sein soll als Wiederholungen zählen, nämlich ein Weg zu einem gesünderen, stärkeren und selbstbewussteren Leben.
insert into public.team_members (name, role_title, bio, qualifications, focus_areas, is_owner, visible, sort_order) values ($str$Nina$str$, $str$Yoga- und Kinderyogalehrerin (NINYASA Yoga)$str$, $str$Unter dem Namen NINYASA Yoga leitet Nina das Yoga- und Kinderyoga-Angebot im Sportpark Pollack – mit Atemübungen, Meditation und verschiedenen Yogastilen für Einsteiger:innen ebenso wie für Fortgeschrittene.$str$, '[]'::jsonb, $json$["Yoga","Kinderyoga"]$json$::jsonb, false, true, 1);
